    case SGM_TAG_F32: return a.u.f32 == b.u.f32;
    case SGM_TAG_F64: return a.u.f64 == b.u.f64;
    case SGM_TAG_DEC: return sgm_dec_cmp(a.u.dec, b.u.dec) == 0;
